INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62328769', 62328769, 'analyze_legacy', 'Mahkamah Agung', 'central', 'PENGADILAN NEGERI KUALA KAPUAS 01', 'satpam', 'Jasa Lainnya', 'E-Purchasing', 'Kalimantan Tengah, Kapuas (Kab.)', 231816000, 'December 2025', 'APBN - RUPIAH MURNI (A)', 1, 1, '( 52, OB, @ 4458000 )', 'Satpam ( 52, OB, @ 4458000 );', 'Tugas Pokok dan Tanggung Jawab : - Pengamanan Fisik & Aset: Melindungi benda bergerak/tidak bergerak, gedung, dan personel dari tindak kriminal seperti pencurian, sabotase, atau perusakan. - Patroli Rutin: Melakukan pengecekan berkala terhadap seluruh area (pintu, pagar, kunci) untuk mendeteksi aktivitas mencurigakan. - Kontrol Akses: Memeriksa identitas karyawan, pengunjung, dan kendaraan yang keluar-masuk (seringkali menggunakan sistem visitor management). - Pemantauan CCTV: Mengawasi monitor keamanan untuk merespons ancaman secara cepat. - Penanganan Darurat: Tanggap cepat terhadap situasi seperti kebakaran, bencana alam, atau gangguan ketertiban umum. - Pelaporan (Reporting): Membuat laporan harian, log insiden, dan catatan patroli secara tertulis atau digital. - Pengaturan Lalu Lintas: Mengatur kendaraan dan orang di area parkir. Kualifikasi dan Persyaratan Umum : - Pendidikan & Pelatihan: Wajib lulus pelatihan Gada Pratama dan memiliki Kartu Tanda Anggota (KTA) resmi. - Kondisi Fisik: Sehat jasmani dan rohani, serta memiliki tubuh yang prima untuk patroli berjalan kaki. - Usia: Umumnya antara 18 hingga 50 tahun. - Catatan: Tidak memiliki catatan kriminal. Keterampilan (Skills) yang Dibutuhkan Kemampuan : - Menilai Situasi: Cepat tanggap dalam mengenali bahaya. - Komunikasi: Mampu berkomunikasi dengan jelas, baik kepada staf maupun otoritas. - Ketelitian & Waspada: Fokus pada detail lingkungan sekitar. - Etika & Pelayanan: Menerapkan prinsip 5S (Senyum, Salam, Sapa, Sopan, Santun). Prosedur Kerja (SOP) Teknis : - Waktu Respon: Target respon untuk ancaman jiwa/kebakaran kurang lebih 3 menit, pencurian/perusakan kurang lebih 5 menit, dan ketidaktertiban kurang lebih 10 menit. - Sistem Shift: Bekerja dalam sistem shift (pagi, sore, malam) selama 24 jam. - Inventaris: Mengelola alat kerja seperti HT (Handy Talky), senter, APAR, dan buku log.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 421428);
