INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65399752', 65399752, 'analyze_legacy', 'Kementerian Dalam Negeri', 'central', 'DITJEN KEPENDUDUKAN DAN PENCATATAN SIPIL', 'Tenaga Ahli Manajemen Proyek Junior', 'Jasa Konsultansi', 'Penunjukan Langsung', 'DKI Jakarta, Jakarta Selatan (Kota)', 126000000, 'February 2026', 'APBN - PINJAMAN LUAR NEGERI (B)', 1, 1, '11 OB', '1. Mendukung pelaksanaan kegiatan harian PMU melalui koordinasi operasional, penyiapan dokumen, dan fasilitasi komunikasi lintas tim.; 2. Membantu menindaklanjuti arahan dan rencana kerja yang telah disusun oleh Project Manager dan PMU, termasuk memastikan setiap kegiatan berjalan sesuai jadwal; 3. Mengumpulkan, memverifikasi, dan menyusun data, laporan perkembangan, serta dokumen pendukung lainnya sebagai bahan monitoring dan evaluasi; 4. Mendukung penyiapan laporan rutin proyek (progress report, minutes of meeting, dan dokumen komunikasi proyek lainnya) sesuai kebutuhan PMU; 5. Membantu koordinasi kegiatan antar pemangku kepentingan di tingkat operasional, termasuk unit teknis, vendor, tenaga pendukung, dan konsultan terkait;', '1. Memiliki latar belakang Pendidikan Sarjana, di bidang ekonomi/bisnis dan manajemen/demografi/statistik/teknologi informasi dan komunikasi, dan lainnya yang dibuktikan dengan ijazah. 2. Memiliki pengalaman minimal 2 tahun pengalaman sebagai Manajemen Proyek (atau yang setara) dibuktikan dengan melampirkan Surat Keterangan Kerja/Kontrak Kerja; 3. Memiliki pengalaman bekerja untuk proyek Pemerintah Indonesia dan/atau yang didanai donor internasional dibuktikan dengan melampirkan Surat Keterangan Kerja/Kontrak Kerja; 4. Sertifikasi dalam bidang Manajemen Proyek (seperti Certified Associate in Project Management/Project Management Professional, atau lainnya) menjadi keunggulan, dibuktikan dengan dokumen pendukung; 5. Memiliki pengalaman mengelola proyek yang melibatkan banyak pemangku kepentingan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 421503);
