INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62365101', 62365101, 'analyze_legacy', 'Mahkamah Agung', 'central', 'PENGADILAN AGAMA PAMEKASAN 01', 'Langganan Internet Pengadilan Agama Pamekasan Tahun Anggaran 2026', 'Jasa Lainnya', 'E-Purchasing', 'Jawa Timur, Pamekasan (Kab.)', 168000000, 'December 2025', 'APBN - RUPIAH MURNI (A)', 1, 1, '( 12, BLN, @ 14000000 )', '1. Langganan Internet ( 12, BLN, @ 14000000 );', 'Dalam rangka mendukung pelaksanaan fungsi dan tugas Pengadilan Agama Pamekasan serta mewujudkan penyelenggaraan peradilan yang modern berbasis pemanfaatan teknologi informasi, diperlukan dukungan akses internet yang andal, stabil, dan berkelanjutan. Oleh karena itu, Pengadilan Agama Pamekasan memerlukan pengadaan Jasa Langganan Internet Dedicated untuk Tahun Anggaran 2026 dengan ketentuan sebagai berikut: 1. Jenis layanan berupa Dedicated Internet Access (DIA) dengan bandwidth simetris 1:1; 2. Kapasitas bandwidth utama sebesar 150 Mbps; 3. Tersedia jaringan cadangan (backup link) berupa koneksi broadband dengan kapasitas minimal 100 Mbps; 4. Media koneksi menggunakan fiber optic sampai dengan lokasi Kantor Pengadilan Agama Pamekasan; 5. Tingkat ketersediaan layanan (uptime) minimal 99% per bulan; 6. Penyedia wajib menyediakan layanan dukungan teknis (helpdesk) selama 24 jam x 7 hari dengan waktu respon gangguan maksimal 1 jam; 7. Masa layanan berlaku selama 12 (dua belas) bulan, terhitung sejak Januari sampai dengan Desember 2026. Spesifikasi ini dimaksudkan untuk menjamin kelancaran operasional aplikasi peradilan, layanan administrasi perkara, serta layanan publik berbasis teknologi informasi di Pengadilan Agama Pamekasan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 425586);
