INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62365136', 62365136, 'analyze_legacy', 'Kementerian Imigrasi dan Pemasyarakatan', 'central', 'IM32 Kantor Wilayah Direktorat Jenderal Imigrasi Kepulauan Riau', 'PENGADAAN SEWA KENDARAAN OPERASIONAL LAPANGAN DI WILAYAH KEPULAUAN RIAU (PULAU BINTAN, BATAM & KARIMUN)', 'Jasa Lainnya', 'E-Purchasing', 'Kepulauan Riau, Tanjung Pinang (Kota) | Kepulauan Riau, Tanjung Pinang (Kota)', 605981000, 'December 2025', 'APBN - RUPIAH MURNI (A)', 1, 1, '5 UNIT', 'PENGADAAN SEWA KENDARAAN OPERASIONAL PEJABAT ESELON II DI WILAYAH KEPULAUAN RIAU 2 UNIT x 12 BULAN (PULAU BINTAN & PULAU BATAM); PENGADAAN SEWA KENDARAAN OPERASIONAL LAPANGAN DI WILAYAH KEPULAUAN RIAU - 3 UNIT x 10 BULAN (PULAU BINTAN, BATAM & KARIMUN);', 'KENDARAAN OPERASIONAL ESELON II: Tipe Mesin: 1GD-FTV, 2.8L 4-Silinder, DOHC, VNT Intercooler. Kapasitas: 2755 cc. Tenaga Maksimal: Sekitar 204 PS (atau 203.9 dk) @ 3000-4000 rpm. Torsi Maksimal: Sekitar 500 Nm @ 1600-2800 rpm. Bahan Bakar: Diesel. Transmisi: Otomatis 6-Speed dengan Sport Sequential Switchmatic. Sistem Penggerak: 4x2. KENDARAAN OPERASIONAL LAPANGAN: Mesin: 1.496 cc, 4-Silinder, 16-Valve, DOHC, Dual VVT-i (Kode 2NR-VEX). Sistem Hibrida: Toyota Hybrid System (THS) dengan Power Split Device. Tenaga Bensin: 91 PS (88 dk) / 5.500 rpm. Torsi Bensin: 121 Nm / 4.000-4.800 rpm. Tenaga Motor Listrik: 80 PS. Torsi Motor Listrik: 141 Nm. Tenaga Kombinasi: 111 PS (109,4 dk). Transmisi: eCVT (Continuously Variable Transmission). Dimensi: Panjang sekitar 4.512 mm (dengan aerokit), Lebar 1.780 mm, Tinggi 1.700 mm, Sumbu Roda 2.750 mm. Ground Clearance: 205 mm.', 240000000, 'high', 'Terdapat indikasi spesifikasi kendaraan terlalu mengarah pada model/kelas tertentu dan penggunaan kendaraan operasional pejabat eselon II selama 12 bulan berpotensi berlebihan. Untuk fungsi operasional pemerintah, kebutuhan sewa seharusnya dapat dipenuhi dengan spesifikasi yang lebih generik dan ekonomis. Porsi kendaraan pejabat dalam paket ini menimbulkan risiko pemborosan anggaran yang signifikan.', NULL, NULL, 3, 1, 1, 1, 1, 425880);
