INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63003035', 63003035, 'analyze_legacy', 'Kab. Sidoarjo', 'kabkota', 'Badan Pelayanan Pajak Daerah', 'Belanja Tinta Printer Hitam', 'Barang', 'E-Purchasing', 'Jawa Timur, Sidoarjo (Kab.)', 3060000, 'January 2026', 'APBD', 1, 1, '30 Buah', 'Uraian pekerjaan Belanja Tinta Printer Hitam untuk Printer Epson ini meliputi kegiatan pengadaan, penyediaan, dan penyerahan tinta printer warna hitam yang digunakan untuk mendukung kelancaran kegiatan administrasi perkantoran, pelayanan publik, serta pencetakan dokumen resmi pada perangkat daerah. Pekerjaan ini mencakup penyediaan tinta printer hitam yang kompatibel dengan printer merek Epson, baik untuk tipe inkjet maupun sistem tinta (ink tank), dengan kualitas cetak yang jelas, tajam, dan tidak mudah luntur. Tinta yang disediakan harus aman digunakan, tidak merusak komponen printer, serta sesuai dengan spesifikasi teknis yang dipersyaratkan', 'Spesifikasi Teknis Tinta Printer Epson 003 (Hitam) 1. Nama Barang Tinta Printer Epson 003 Hitam 2. Jenis Barang Bahan Habis Pakai Perangkat Cetak (Consumable Printer) 3. Merek / Tipe Kompatibel untuk Printer Epson Kode tinta: 003 Warna: Hitam (Black) 4. Jenis Tinta Tinta Dye-based (sesuai standar Epson) 5. Volume Isi bersih: ± 65 ml 6. Kompatibilitas Printer Digunakan untuk printer Epson seri EcoTank, antara lain: Epson L3110 Epson L3150 Epson L5190 Epson L1110 Epson L1210 Epson L1250 Epson L3210 Epson L3250 Epson L3251 Epson L5290 Atau seri Epson EcoTank lain yang menggunakan tinta kode 003 7. Kualitas Cetak Hasil cetak tajam dan jelas Warna hitam pekat Tidak mudah pudar Tidak menyebabkan penyumbatan nozzle 8. Karakteristik Teknis Aman untuk print head Epson Tidak merusak sistem tinta Konsistensi tinta stabil Daya serap baik pada kertas HVS dan kertas standar lainnya 9. Kemasan Botol asli pabrikan Segel utuh dan belum dibuka Dilengkapi tutup anti tumpah 10. Kondisi Barang Baru (bukan rekondisi) Bukan tinta isi ulang Tidak kedaluwarsa 11. Standar Mutu Memenuhi standar mutu pabrikan Epson Direkomendasikan tinta original atau setara kualitasnya 12. Jumlah Sesuai kebutuhan dan tercantum dalam kontrak atau surat pesanan 13. Tempat dan Waktu Pengiriman Lokasi: Sesuai penetapan PPK/Pejabat Pengadaan Waktu: Sesuai ketentuan dalam kontrak/SP 14. Pemeriksaan dan Serah Terima Diperiksa oleh PPK Dibuktikan dengan Berita Acara Serah Terima (BAST)', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 427864);
